/**
 * @distilled.cloud/starburst-galaxy -- Starburst Galaxy SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from Galaxy's public OpenAPI documents,
 * mirrored at `specs/spec-mirror-starburst-galaxy/specs/`. Everything else in
 * this folder is hand-written.
 *
 * One module per Galaxy API service: `cluster`, `catalog`, `role`,
 * `privilege`, `serviceAccount`, `dataProduct`, `tag`, ….
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as StarburstGalaxy from "@distilled.cloud/starburst-galaxy";
 *
 * const program = Effect.gen(function* () {
 *   const { result } = yield* StarburstGalaxy.cluster.listClusters({});
 *   const [first] = result;
 *   if (first === undefined) return undefined;
 *
 *   const cluster = yield* StarburstGalaxy.cluster.getCluster({ clusterId: first.clusterId });
 *   yield* Effect.log(`${cluster.name}: ${cluster.clusterState} at ${cluster.trinoUri}`);
 *   return cluster;
 * });
 *
 * const Live = Layer.mergeAll(
 *   StarburstGalaxy.CredentialsFromEnv,
 *   StarburstGalaxy.StarburstGalaxyProtocol,
 * ).pipe(Layer.provideMerge(FetchHttpClient.layer));
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  StarburstGalaxyProtocol,
  type StarburstGalaxyOpError,
  type StarburstGalaxyOpContext,
} from "./protocol.ts";
export { paginateToken } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
